const CUSTOM_IDEAS={"en": [["Lake Toba and Batak culture", "A lakeside stay, time on Samosir and a chance to explore Batak villages. Combine it with your jungle trek or shape a separate journey."], ["Volcanoes and highlands", "Discuss Berastagi, Sibayak or a longer mountain route, matched to your fitness, dates and local conditions."], ["Coast and island time", "Consider a slower finish by the sea or an island stay. We’ll discuss destinations, transfers and the time you have."]], "es": [["Lago Toba y cultura batak", "Una estancia junto al lago, tiempo en Samosir y pueblos batak. Combínalo con tu trek o diseña otro viaje."], ["Volcanes y tierras altas", "Consulta Berastagi, Sibayak o una ruta de montaña más larga según tu forma física, fechas y condiciones."], ["Costa e islas", "Termina con calma junto al mar o en una isla. Hablaremos de destinos, traslados y del tiempo disponible."]], "de": [["Tobasee und Batak-Kultur", "Zeit am See, auf Samosir und in Batak-Dörfern. Mit deinem Trek kombinieren oder separat planen."], ["Vulkane und Hochland", "Berastagi, Sibayak oder eine längere Bergroute, abgestimmt auf Fitness, Termine und Bedingungen."], ["Küste und Inseln", "Ein ruhiger Abschluss am Meer oder auf einer Insel. Ziele, Transfers und verfügbare Zeit besprechen wir gemeinsam."]], "fr": [["Lac Toba et culture batak", "Un séjour au lac, Samosir et les villages batak. À combiner avec votre trek ou en voyage séparé."], ["Volcans et hauts plateaux", "Berastagi, Sibayak ou une route en montagne selon votre forme, vos dates et les conditions."], ["Côte et îles", "Une fin de séjour tranquille à la mer ou sur une île. Nous discuterons des destinations, transferts et du temps disponible."]], "it": [["Lago Toba e cultura batak", "Un soggiorno sul lago, Samosir e villaggi batak. Da abbinare al trek o organizzare separatamente."], ["Vulcani e altopiani", "Berastagi, Sibayak o un percorso in montagna secondo forma fisica, date e condizioni."], ["Costa e isole", "Concludi con calma al mare o su un’isola. Parliamo di destinazioni, trasferimenti e tempo disponibile."]], "nl": [["Tobameer en Batak-cultuur", "Een verblijf aan het meer, Samosir en Batak-dorpen. Combineer het met je trek of plan een aparte reis."], ["Vulkanen en hooglanden", "Bespreek Berastagi, Sibayak of een langere bergroute, passend bij conditie, data en omstandigheden."], ["Kust en eilanden", "Een rustig einde aan zee of op een eiland. We bespreken bestemmingen, transfers en beschikbare tijd."]], "pt": [["Lago Toba e cultura batak", "Uma estadia junto ao lago, Samosir e aldeias batak. Combine com o trek ou planeie uma viagem separada."], ["Vulcões e terras altas", "Berastagi, Sibayak ou uma rota de montanha conforme a forma física, as datas e as condições."], ["Costa e ilhas", "Um final tranquilo junto ao mar ou numa ilha. Conversamos sobre destinos, transferes e tempo disponível."]]};

const TRAIL_STORIES={"en": [["Into the canopy", "The day begins in Bukit Lawang with a guide briefing, then follows the rainforest trails into Gunung Leuser. There is time to watch the canopy, learn about forest plants and pause for lunch and tropical fruit. Wildlife moves freely; each walk unfolds in its own way."], ["An evening by the river", "An overnight trek brings a change of pace at the riverside campsite. Dinner gives way to the sounds of the rainforest, and morning starts with breakfast in the jungle. On the two-day tour, the return includes traditional river tubing to Bukit Lawang."], ["Time to go deeper", "With two to four nights in the rainforest, the longer tours leave room for more trails, different camps and quiet stops beside the river. Guides share their knowledge of wildlife and the forest. A final morning walk leads into the return journey, with river conditions shaping the plans."]], "es": [["Bajo el dosel", "El día empieza en Bukit Lawang con una charla del guía antes de seguir los senderos de Gunung Leuser. Hay tiempo para observar las copas, conocer las plantas y parar a comer fruta tropical. La fauna se mueve libremente y cada caminata es distinta."], ["Una tarde junto al río", "El trek con noche cambia de ritmo al llegar al campamento del río. Tras la cena se escuchan los sonidos de la selva y la mañana empieza con un desayuno entre árboles. En el tour de dos días, el regreso incluye tubing tradicional hasta Bukit Lawang."], ["Tiempo para ir más lejos", "De dos a cuatro noches permiten explorar más senderos, distintos campamentos y paradas tranquilas junto al río. Los guías comparten sus conocimientos de fauna y selva. Una última caminata da paso al regreso, según las condiciones del río."]], "de": [["Unter dem Blätterdach", "Der Tag beginnt mit einer Einweisung in Bukit Lawang, bevor die Pfade in Gunung Leuser führen. Zeit, die Baumkronen zu beobachten, Pflanzen kennenzulernen und mit Mittagessen und tropischem Obst zu pausieren. Tiere bewegen sich frei; jeder Weg ist anders."], ["Ein Abend am Fluss", "Im Flusscamp wird das Tempo ruhiger. Auf das Abendessen folgen die Geräusche des Regenwalds; der Morgen beginnt mit Frühstück im Dschungel. Bei der Zweitagestour gehört traditionelles Tubing zurück nach Bukit Lawang dazu."], ["Zeit für tiefere Wege", "Zwei bis vier Nächte erlauben mehr Pfade, verschiedene Camps und stille Pausen am Fluss. Guides teilen ihr Wissen über Tiere und Wald. Nach einer letzten Morgenwanderung beginnt die Rückkehr, angepasst an die Flussbedingungen."]], "fr": [["Sous la canopée", "La journée commence par les explications du guide à Bukit Lawang, puis les sentiers entrent dans Gunung Leuser. Observer les arbres, découvrir les plantes, déjeuner et goûter des fruits tropicaux. La faune se déplace librement; chaque marche est différente."], ["Un soir près de la rivière", "Le rythme ralentit au camp près de la rivière. Le dîner laisse place aux sons de la forêt; le matin commence par le petit-déjeuner dans la jungle. Le tour de deux jours comprend le retour en tubing traditionnel à Bukit Lawang."], ["Le temps d’aller plus loin", "Deux à quatre nuits donnent le temps de parcourir d’autres sentiers, différents camps et des pauses près de la rivière. Les guides partagent leurs connaissances de la faune et de la forêt. Une dernière marche précède le retour, selon les conditions de la rivière."]], "it": [["Sotto la volta verde", "La giornata comincia con le indicazioni della guida a Bukit Lawang prima dei sentieri di Gunung Leuser. Tempo per osservare la chioma, conoscere le piante e fermarsi per pranzo e frutta tropicale. Gli animali si muovono liberi; ogni camminata è diversa."], ["Una sera al fiume", "Il ritmo rallenta al campo sul fiume. La cena lascia spazio ai suoni della foresta e il mattino comincia con la colazione nella giungla. Il tour di due giorni include il rientro in tubing tradizionale a Bukit Lawang."], ["Tempo per andare più lontano", "Da due a quattro notti permettono più sentieri, campi diversi e pause tranquille al fiume. Le guide condividono la loro conoscenza della fauna e della foresta. Un’ultima camminata precede il ritorno, secondo le condizioni del fiume."]], "nl": [["Onder het bladerdak", "De dag begint met uitleg van de gids in Bukit Lawang en volgt de paden naar Gunung Leuser. Tijd voor het bladerdak, bosplanten, lunch en tropisch fruit. Dieren bewegen vrij; elke wandeling is anders."], ["Een avond aan de rivier", "Het tempo vertraagt in het rivierkamp. Na het diner klinken de geluiden van het regenwoud; de ochtend begint met ontbijt in de jungle. De tweedaagse tour omvat traditioneel tubing terug naar Bukit Lawang."], ["Tijd om verder te gaan", "Twee tot vier nachten geven ruimte voor meer paden, verschillende kampen en rustige rivierpauzes. Gidsen delen hun kennis van dieren en bos. Na een laatste ochtendwandeling volgt de terugkeer, afhankelijk van de rivieromstandigheden."]], "pt": [["Sob a copa", "O dia começa com as orientações do guia em Bukit Lawang, antes dos trilhos de Gunung Leuser. Tempo para observar as copas, conhecer plantas e parar para almoço e fruta tropical. Os animais movem-se livremente; cada caminhada é diferente."], ["Uma tarde junto ao rio", "O ritmo abranda no acampamento junto ao rio. O jantar dá lugar aos sons da floresta e a manhã começa com o pequeno-almoço na selva. O tour de dois dias inclui regresso em tubing tradicional a Bukit Lawang."], ["Tempo para ir mais longe", "Duas a quatro noites permitem mais trilhos, diferentes acampamentos e pausas tranquilas junto ao rio. Os guias partilham conhecimentos da fauna e floresta. Uma última caminhada antecede o regresso, conforme as condições do rio."]]};
function renderCommunity(){
 q('#team-grid').classList.add('team-partnership');
 q('#team-grid').innerHTML=`<figure class="team-group"><img src="/assets/photos/team-partnership.webp" alt="${escapeHTML(t('teamCaption'))}" width="1350" height="1800" loading="lazy"><figcaption>${escapeHTML(t('teamCaption'))}</figcaption></figure><div><h3>${escapeHTML(t('partnershipTitle'))}</h3><p>${escapeHTML(t('partnershipStory'))}</p><div class="team-names"><span>Sandy<small>Chief Experience Officer</small></span><span>Asier<small>CEO</small></span><span>Nacho<small>COO</small></span></div></div>`;
 q('#story-grid').innerHTML=TRAIL_STORIES[lang].map(([title,body])=>`<article class="sample-story trail-story"><h3>${escapeHTML(title)}</h3><p class="story-text">${escapeHTML(body)}</p></article>`).join('');
}

