const LANG_NAMES={en:'English',es:'Español',de:'Deutsch',fr:'Français',it:'Italiano',nl:'Nederlands',pt:'Português'};
const PHONE='34615788239';
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wa=text=>'https://wa.me/'+PHONE+'?text='+encodeURIComponent(text);
let lang='en',lastTrigger=null;
try{const saved=new URLSearchParams(location.search).get('lang')||localStorage.getItem('sumatra-language')||navigator.language.split('-')[0];if(UI[saved])lang=saved}catch{}
const t=key=>UI[lang][key];
const money=value=>new Intl.NumberFormat(lang,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(value);
function duration(route){return route.days+' '+(route.days===1?t('daySingular'):t('days'))}
function factline(route){return duration(route)+(route.nights?' · '+route.nights+' '+(route.nights===1?t('night'):t('nights')):'')}
function priceBlock(route){const p=route.pricing;if(p.amount===null&&!p.group_rates.length)return `<span class="quote-price">${escapeHTML(t('quote'))}</span>`;const value=p.group_rates.length?Math.min(...p.group_rates.map(r=>r.amount_per_person)):p.amount;const label=p.group_rates.length?t('from'):(p.status==='supplied'?t('pricePerPerson'):t(p.status==='proposed'?'proposed':'suggested'));return `<small>${escapeHTML(label)}</small><strong>${money(value)}</strong>${p.minimum_participants===2?`<span class="price-condition">${escapeHTML(t('minimumTwo'))}</span>`:''}`}
function renderRoutes(){q('#tour-grid').innerHTML=ROUTES.map((route,i)=>{const r=R[lang][i];return `<article class="tour-card"><div class="tour-photo"><img src="/assets/${route.img}" alt="${escapeHTML(route.photoAlt)}" style="object-position:${route.photoPosition}" loading="lazy" width="600" height="450"><span class="tag">${escapeHTML(factline(route))}</span></div><div class="card-body"><h3>${escapeHTML(r.title)}</h3><p>${escapeHTML(r.description)}</p><div class="card-bottom"><div class="price">${priceBlock(route)}</div><button data-route="${i}">${escapeHTML(t('viewRoute'))}</button>${[0,1,2,3,4].includes(i)?`<a class="book-link" href="/book/${route.id.toLowerCase()}">${lang==='es'?'Reservar y pagar':'Book & pay'} ↗</a>`:''}</div></div></article>`}).join('');qa('[data-route]').forEach(b=>b.addEventListener('click',()=>openRoute(Number(b.dataset.route),b)));q('#custom-grid').innerHTML=CUSTOM_IDEAS[lang].map(([title,body],i)=>`<article class="custom-idea"><span class="custom-label">${escapeHTML(t('customLabel'))}</span><h3>${escapeHTML(title)}</h3><p>${escapeHTML(body)}</p><button class="text-link" data-custom="${i}">${escapeHTML(t('customButton'))}</button></article>`).join('');qa('[data-custom]').forEach(b=>b.addEventListener('click',()=>chooseCustom(Number(b.dataset.custom))));}
function chooseCustom(i){q('#tour').value='custom';if(i!==undefined){const idea=CUSTOM_IDEAS[lang][i][0];const note=t('customPrompt')+': '+idea;if(!q('#notes').value.includes(idea))q('#notes').value=[q('#notes').value.trim(),note].filter(Boolean).join('\n');}q('#enquiry').scrollIntoView({behavior:'smooth'});q('#date').focus({preventScroll:true});}
function list(items){return items?`<ul>${items.map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul>`:`<p>${escapeHTML(t('notSupplied'))}</p>`;}
function tourItinerary(route,r){if(lang!=='en')return list(r.itinerary.map(line=>t('day')+' '+line));return `<div class="source-itinerary">${route.fullItinerary.split('\n').map(line=>{const clean=line.trim().replace(/^- /,'');if(!clean)return '';return /^(?:Day \d|DAY \d|\d{2}:\d{2})/.test(clean)?`<h4>${escapeHTML(clean)}</h4>`:`<p>${escapeHTML(clean)}</p>`;}).join('')}</div>`;}
function openRoute(i,trigger){lastTrigger=trigger;const route=ROUTES[i],r=R[lang][i],p=route.pricing;let rates='';if(p.group_rates.length)rates=`<h3>${escapeHTML(t('groupRates'))}</h3><table class="group-price-table"><thead><tr><th>${escapeHTML(t('groupSize'))}</th><th>${escapeHTML(t('pricePerPerson'))}</th></tr></thead><tbody>${p.group_rates.map(rate=>`<tr><td>${rate.min_people===rate.max_people?rate.min_people:rate.min_people+'–'+rate.max_people}</td><td>${money(rate.amount_per_person)}</td></tr>`).join('')}</tbody></table><p class="small">${escapeHTML(t('groupNote'))}</p>`;q('#tour-detail').innerHTML=`<article class="detail"><h2 id="detail-title">${escapeHTML(r.title)}</h2><p>${escapeHTML(r.description)}</p><div class="detail-facts"><span>${escapeHTML(factline(route))}</span><span>${escapeHTML(t('start'))}: 09:00 · BUKIT LAWANG</span></div>${lang==='en'?`<p class="small">${escapeHTML(t('returnLabel'))}: ${escapeHTML(route.returnTime)}${route.difficulty?' · '+escapeHTML(t('difficulty'))+': '+escapeHTML(route.difficulty):''}${i===0?' · Approximately 6–7 hours · Private or shared':i===4?' · Private guided jungle trekking':''}</p>`:''}<div class="detail-price price">${priceBlock(route)}<span class="price-condition">${escapeHTML(t('perPerson'))}</span></div>${rates}${i===0?`<p class="small">${escapeHTML(t('oneDayNote'))}</p>`:''}<img class="detail-photo" src="/assets/${route.img}" alt="${escapeHTML(route.photoAlt)}" style="object-position:${route.photoPosition}"><h3>${escapeHTML(t('itinerary'))}</h3>${tourItinerary(route,r)}<h3>${escapeHTML(t('includes'))}</h3>${list(r.included)}<h3>${escapeHTML(t('excludes'))}</h3>${list(r.excluded)}${r.packing?`<h3>${escapeHTML(t('packing'))}</h3>${list(r.packing)}`:''}<p class="small">${escapeHTML(t('wildAnswer'))}</p><p class="small">${escapeHTML(t('priceNote'))}</p><button class="button primary" id="choose-route">${escapeHTML(t('book'))}</button></article>`;q('#tour-dialog').setAttribute('aria-labelledby','detail-title');q('#tour-dialog').showModal();document.body.classList.add('modal-open');q('#tour-dialog').scrollTop=0;q('#choose-route').addEventListener('click',()=>{q('#tour').value=String(i);q('#tour-dialog').close();q('#enquiry').scrollIntoView({behavior:'smooth'});q('#date').focus({preventScroll:true});});}
function applyLanguage(){document.documentElement.lang=lang;q('#language').value=lang;document.title='Explore Sumatra Escape · '+t('navRoutes');qa('[data-t]').forEach(el=>{const key=el.dataset.t;if(!UI[lang][key])throw new Error('Missing '+lang+':'+key);if(['hero','routesTitle','enquiryTitle','teamTitle'].includes(key))el.innerHTML=t(key);else el.textContent=t(key)});q('#language').setAttribute('aria-label',t('messageLanguage'));q('.close-dialog').setAttribute('aria-label',t('close'));const tourValue=q('#tour').value;q('#tour').innerHTML=ROUTES.map((r,i)=>`<option value="${i}">${escapeHTML(R[lang][i].title)}</option>`).join('')+`<option value="custom">${escapeHTML(t('custom'))}</option>`;if(tourValue)q('#tour').value=tourValue;renderRoutes();renderCommunity();renderPhotoGallery();['#phone','#floating-chat'].forEach(s=>q(s).href=wa(t('messageHello')));q('#notes').placeholder=t('notesLabel');q('#credits').textContent=t('originalPhotoCredits');try{localStorage.setItem('sumatra-language',lang);const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u)}catch{}}
q('#language').addEventListener('change',e=>{lang=e.target.value;applyLanguage()});q('.close-dialog').addEventListener('click',()=>q('#tour-dialog').close());q('#tour-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');if(lastTrigger?.isConnected)lastTrigger.focus({preventScroll:true})});q('#tour-dialog').addEventListener('click',e=>{if(e.target===q('#tour-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const now=new Date();q('#date').min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
function enquiryURL(){const value=q('#tour').value;const title=value==='custom'?t('custom'):R[lang][Number(value)].title;const lines=[t('messageHello'),'',t('tourLabel')+': '+title,t('messageDate')+': '+q('#date').value,t('messagePeople')+': '+q('#travellers').value,t('messageName')+': '+q('#name').value.trim(),t('messageLanguage')+': '+LANG_NAMES[lang]];if(q('#notes').value.trim())lines.push(t('messageNotes')+': '+q('#notes').value.trim());return wa(lines.join('\n'))}
q('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const link=document.createElement('a');link.href=enquiryURL();link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove()});
q('#custom-enquiry').addEventListener('click',()=>chooseCustom());
applyLanguage();

const PAY_COPY={en:['Pay securely ↗','Confirm a quote first','Email for your booking','Test payments only — no real money is charged. Your preferred departure date will be confirmed by our team.','Starting checkout…'],es:['Pagar de forma segura ↗','Confirma primero un presupuesto','Email para tu reserva','Pagos de prueba: no se cobra dinero real. Nuestro equipo confirmará la fecha de salida solicitada.','Abriendo el pago…'],de:['Sicher bezahlen ↗','Zuerst Angebot bestätigen','E-Mail für deine Buchung','Nur Testzahlungen: Es wird kein echtes Geld belastet. Unser Team bestätigt deinen gewünschten Abreisetag.','Zahlung wird geöffnet…'],fr:['Payer en toute sécurité ↗','Confirmez d’abord un devis','E-mail pour votre réservation','Paiements de test : aucun argent réel n’est débité. Notre équipe confirmera votre date de départ souhaitée.','Ouverture du paiement…'],it:['Paga in sicurezza ↗','Conferma prima un preventivo','Email per la prenotazione','Solo pagamenti di prova: non viene addebitato denaro reale. Il team confermerà la data richiesta.','Apertura del pagamento…'],nl:['Veilig betalen ↗','Bevestig eerst een offerte','E-mail voor je boeking','Alleen testbetalingen: er wordt geen echt geld afgeschreven. Ons team bevestigt je gewenste vertrekdatum.','Betaling openen…'],pt:['Pagar com segurança ↗','Confirme primeiro um orçamento','Email para a sua reserva','Apenas pagamentos de teste: não é cobrado dinheiro real. A equipa confirmará a data pretendida.','A abrir o pagamento…']};
const payButton=document.querySelector('#pay-button'),payEmail=document.querySelector('#booking-email'),payStatus=document.querySelector('#pay-status');
let checkoutRef=null,checkoutDetails=null;
function payCopy(){return PAY_COPY[document.documentElement.lang]||PAY_COPY.en;}
function updatePay(){const c=payCopy(),value=document.querySelector('#tour').value;payButton.disabled=!['0','1','2','3','4'].includes(value);payButton.textContent=payButton.disabled?c[1]:c[0];document.querySelector('#booking-email-label').textContent=c[2];document.querySelector('#pay-note').textContent=c[3];}
document.querySelector('#tour').addEventListener('change',updatePay);document.querySelector('#language').addEventListener('change',updatePay);document.addEventListener('click',e=>{if(e.target.closest('#choose-route,[data-custom],#custom-enquiry'))updatePay();});
payButton.addEventListener('click',async()=>{
 const form=document.querySelector('#enquiry-form');payEmail.required=true;
 if(!form.reportValidity()){payEmail.required=false;return;}payEmail.required=false;
 const selected=document.querySelector('#tour').value;
 const b={tour:selected==='1'?'BL-02D':selected==='2'?'BL-03D':'',travellers:Number(document.querySelector('#travellers').value),departure:document.querySelector('#date').value,name:document.querySelector('#name').value,email:payEmail.value};
 const details=JSON.stringify(b);if(checkoutDetails!==details){checkoutRef=crypto.randomUUID();checkoutDetails=details;}b.id=checkoutRef;
 payButton.disabled=true;payStatus.textContent=payCopy()[4];
 try{const response=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Please try again.');const u=new URL(data.url);if(u.protocol!=='https:'||!['checkout.stripe.com','buy.stripe.com'].includes(u.hostname))throw new Error('Unexpected payment destination.');location.assign(u.href);}
 catch(error){payStatus.textContent=error.message;updatePay();}
});updatePay();
